// Example: A function that fetches data from an external API
function fetchData() {
  return new Promise((resolve, reject) => {
    https.get('https://api.example.com/data', (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(JSON.parse(data)));
    }).on('error', reject);
  });
}

